import{z as l,x as s,o as i,c as d,q as n,j as o,D as A,d as e,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"大数据与调查的融合","description":"","frontmatter":{"title":"大数据与调查的融合","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-bigdata-survey-fusion.md","filePath":"econ/ec-bigdata-survey-fusion.md","lastUpdated":1791413859000}'),p={name:"econ/ec-bigdata-survey-fusion.md"};function m(c,a,u,F,D,C){const t=s("Mermaid");return i(),d("div",null,[a[2]||(a[2]=n('<h1 id="大数据与调查的融合" tabindex="-1">大数据与调查的融合 <a class="header-anchor" href="#大数据与调查的融合" aria-label="Permalink to &quot;大数据与调查的融合&quot;">​</a></h1><div class="epigraph"><p>更多数据不会自动稀释偏差；大样本只是把采样管子已有的形状画得更清楚。</p><footer>—— 据 Lazer 等, The Parable of Google Flu: Traps in Big Data Analysis, Science 2014 整理</footer></div><p><a href="/econ/ec-administrative-data">上一课</a>把行政数据的利用钉在流程、口径与进入协议上；行政之外，扫描仪、网页、手机与信用卡还在产出另一种「大」。缺口是：这些大数据与调查究竟是替代还是互补？答案是互补，而且互补得有计量结构——本课把它写清楚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大数据有三种偏。覆盖偏：在平台里的人不是总体，用手机支付的人与用现金的人消费结构不同。行为偏：写评论、做搜索、点广告的不是全体用户。度量偏：字段是商业定义，「活跃用户」「成交」随产品改版而变。调查这边也不轻松：回答率长期下滑有系统记录（Meyer–Mok–Sullivan 2015），无应答不再可忽略，长回顾期的回忆误差放大，成本把样本量压小。<span class="marginnote">初学者容易以为「样本够大偏差就消失了」——实际上大样本只压小随机误差（方差），系统性偏差一点不稀释：一亿条只来自 iPhone 用户的消费记录，永远测不出用现金的老年人的支出。「大」和「准」是两回事。</span>两边的误差结构接近正交：调查小而偏得可描述——有抽样框，知道偏差往哪去；大数据大而偏，且偏随商业逻辑漂移。融合要回答的问题因此不是「用哪个」，而是：偏能不能被校？</p><h3 id="数据组合的计量结构" tabindex="-1">数据组合的计量结构 <a class="header-anchor" href="#数据组合的计量结构" aria-label="Permalink to &quot;数据组合的计量结构&quot;">​</a></h3><p><span class="marginnote">Google 流感趋势在 2012–13 流感季把流感就诊率高估了一倍以上：搜索引擎改版与媒体驱动的搜索行为变化，让偏移本身在漂移。Lazer 等称之为「大数据自大」——它已成为教材级反例。</span></p><p>数据组合不是工程杂活，是估计问题：Ridder–Moffitt 2007 把它收进计量经济学。分工是金标准小样本负责测量与锚点——定义构念、校准总量、估计偏差函数；大样本负责条件变异与精度。链接是第一道工序：Fellegi–Sunter 1969 的概率匹配把「同名同生日」变成带估计误差率的决策，链接误差以测量误差的身份进账。<span class="marginnote">概率链接就是把「两条记录是不是同一个人」从拍脑袋变成打分：同名同生日加分、电话一致加分，总分过阈值才判匹配，连「判错的概率有多大」都一并估出来——链接误差由此从黑箱变成可入账的测量误差。</span>校准是第二道：用调查的代表性权重对大数据重加权，使其在已知总体矩上一致。<span class="marginnote">重加权的一个数字实例：若平台用户里年轻人占七成、总体只占三成，就给年轻人的每条记录乘 3/7（约 0.43）、其他人群按比例放大，使加权后的年龄结构与普查对齐。但权重只修「谁在样本里」的差，修不了「字段本身在测什么」的错。</span>nowcasting 是典型应用：Choi–Varian 2012 用搜索量把当期宏观量「现在化」，其兴衰正是本课边界段的样本。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',9)),(i(),o(B,null,{default:A(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SVY%5B%22%E8%B0%83%E6%9F%A5%3A%20%E5%B0%8F%E8%80%8C%E5%87%86%2C%20%E6%9C%89%E6%8A%BD%E6%A0%B7%E6%A1%86%22%5D%20--%3E%20LN%5B%22%E6%A6%82%E7%8E%87%E9%93%BE%E6%8E%A5%3A%20Fellegi-Sunter%22%5D%0A%20%20BIG%5B%22%E5%A4%A7%E6%95%B0%E6%8D%AE%3A%20%E5%A4%A7%E8%80%8C%E5%81%8F%2C%20%E5%81%8F%E9%9A%8F%E5%95%86%E4%B8%9A%E9%80%BB%E8%BE%91%E6%BC%82%22%5D%20--%3E%20LN%0A%20%20LN%20--%3E%20CAL%5B%22%E7%94%A8%E8%B0%83%E6%9F%A5%E7%9F%A9%E6%A0%A1%E5%87%86%2F%E9%87%8D%E5%8A%A0%E6%9D%83%E5%A4%A7%E6%95%B0%E6%8D%AE%22%5D%0A%20%20MON%5B%22%E6%BC%82%E7%A7%BB%E7%9B%91%E6%B5%8B%3A%20%E5%81%8F%E7%A7%BB%E7%A8%B3%E5%AE%9A%E6%80%A7%E6%A3%80%E9%AA%8C%22%5D%20--%3E%20CAL%0A%20%20CAL%20--%3E%20EST%5B%22%E8%9E%8D%E5%90%88%E4%BC%B0%E8%AE%A1%3A%20%E5%81%8F%E5%B7%AE%E5%87%BD%E6%95%B0%E5%8F%AF%E4%BC%B0%E6%89%8D%E6%9C%89%E6%84%8F%E4%B9%89%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"流程分三步。先各自体检：调查的应答机制写在抽样框旁，大数据的进入机制写在采集脚本旁。再选组合方式：链接——同一对象两源都有标识；校准——两源测同一构念但覆盖不同；镶套——大数据找候选、小样本人工核验。最后登记误差从哪进来：链接误配率、覆盖差、校准矩自身的抽样误差；每一项都要有估计，而不是一句「误差可控」。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("「大数据加小金标准」优于任何单一来源的条件是偏的稳定性。调查给出无偏但高方差的锚，大数据给出低方差但有系统偏移的信号，组合后的均方误差由偏差函数能不能被小样本估出来决定：偏稳定，校一次用一片；偏漂移——平台改版、搜索行为随媒体周期变——校不胜校，GFT 是教案。这与"),E("a",{href:"/econ/ec-administrative-data"},"上一课"),e("同构：先写清谁不在样本里，再谈加权。加权能救覆盖差，救不了构念错位——两源测的根本不是一个量时，链接再准也没用。")],-1)),a[6]||(a[6]=E("p",null,"组合为什么能赢、什么时候翻车，可以画成一条分叉：分歧点只有一个——偏稳不稳。",-1)),(i(),o(B,null,{default:A(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%81%8F%E7%A8%B3%E5%AE%9A%E5%90%97%3F%22%7D%20--%3E%7C%22%E7%A8%B3%E5%AE%9A%22%7C%20A%5B%22%E5%B0%8F%E6%A0%B7%E6%9C%AC%E4%BC%B0%E4%B8%80%E6%AC%A1%E5%81%8F%E5%B7%AE%E5%87%BD%E6%95%B0%22%5D%0A%20%20A%20--%3E%20B%5B%22%E6%A0%A1%E5%87%86%E5%A4%A7%E6%95%B0%E6%8D%AE%2C%20%E5%81%8F%E5%B7%AE%E5%8F%AF%E6%B2%BF%E7%94%A8%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BB%84%E5%90%88%E8%AF%AF%E5%B7%AE%E5%B0%8F%E4%BA%8E%E4%BB%BB%E4%B8%80%E5%8D%95%E6%BA%90%22%5D%0A%20%20Q%20--%3E%7C%22%E6%BC%82%E7%A7%BB%22%7C%20D%5B%22%E5%B9%B3%E5%8F%B0%E6%94%B9%E7%89%88%E6%88%96%E8%A1%8C%E4%B8%BA%E9%9A%8F%E5%AA%92%E4%BD%93%E5%8F%98%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%97%A7%E6%A0%A1%E5%87%86%E5%A4%B1%E6%95%88%2C%20%E5%81%8F%E7%A7%BB%E6%8D%A2%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%A0%A1%E4%B8%8D%E8%83%9C%E6%A0%A1%3A%20GFT%20%E5%BC%8F%E7%BF%BB%E8%BD%A6%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>不这么做会错在哪：拿大数据的样本内总量直接当总体统计量发布；把链接成功率当成一百；用今天的平台口径回放历史行为，还报告「长期规律」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>文本形态的大数据要过<a href="/econ/pm-text-as-data">文本作为数据</a>的三重验证，本课不重讲测量。融合不改变识别设计的要求：组合之后再做因果解释，仍回到<a href="/econ/potential-outcomes">潜在结果</a>的语言。行政与大数据的边界也在模糊——平台数据本质是私有的行政数据，进入协议比统计机构更不透明，上一课的协议思维照用。方法论沉底为一条：先问两源总体的差，再问组合省什么；反过来问，会把工程做成装饰。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大数据三偏：覆盖、行为、度量；偏随商业逻辑漂移，这是它与抽样误差的本质区别。</li><li>融合的计量结构：小金标准定测量与锚点，大样本供变异与精度；链接与校准都有误差进账。</li><li>偏稳定才可校；GFT 的失败不在数据少，在偏移本身漂移。</li><li>调查的价值从「唯一的量」转向「校准的锚」；回答率下滑让它更贵也更关键。</li><li>出处：Ridder and Moffitt, Handbook of Econometrics 2007；Fellegi and Sunter, <em>JASA</em> 1969；Choi and Varian, <em>Economic Record</em> 2012；Lazer 等, <em>Science</em> 2014；Meyer, Mok and Sullivan, <em>JEP</em> 2015。</li></ul>',5))])}const b=l(p,[["render",m]]);export{h as __pageData,b as default};
